import { test, expect } from '@playwright/test';

test.describe('Multi-step form progress indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/multi-step-form');
  });

  test('should display progress indicator on initial load', async ({ page }) => {
    // Verify progress indicator is visible
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Verify it shows step 1 of total steps
    const stepText = page.getByText(/Step 1 of \d+/);
    await expect(stepText).toBeVisible();
  });

  test('should update progress indicator when moving to next step', async ({ page }) => {
    // Fill first step form
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    // Click next button
    const nextButton = page.getByRole('button', { name: /Next/i });
    await nextButton.click();

    // Verify progress indicator updated
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Verify step counter updated
    const stepText = page.getByText(/Step 2 of \d+/);
    await expect(stepText).toBeVisible();
  });

  test('should show completed steps in progress indicator', async ({ page }) => {
    // Complete first step
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    const nextButton = page.getByRole('button', { name: /Next/i });
    await nextButton.click();

    // Verify step 1 is marked as completed
    const completedStep = page.getByRole('img', { name: /step 1 completed/i });
    await expect(completedStep).toBeVisible();

    // Verify current step is highlighted
    const currentStepIndicator = page.getByRole('img', { name: /step 2 current/i });
    await expect(currentStepIndicator).toBeVisible();
  });

  test('should display progress percentage', async ({ page }) => {
    // Check initial progress percentage
    const progressPercentage = page.getByText(/0%|25%/);
    await expect(progressPercentage).toBeVisible();

    // Fill and proceed to next step
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    const lastNameInput = page.getByLabel('Last Name');
    await lastNameInput.fill('Doe');

    const nextButton = page.getByRole('button', { name: /Next/i });
    await nextButton.click();

    // Verify progress percentage increased
    const updatedPercentage = page.getByText(/25%|50%/);
    await expect(updatedPercentage).toBeVisible();
  });

  test('should maintain progress indicator on form validation error', async ({ page }) => {
    // Try to proceed without filling required fields
    const nextButton = page.getByRole('button', { name: /Next/i });
    await nextButton.click();

    // Verify progress indicator is still visible
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Verify still on step 1
    const stepText = page.getByText(/Step 1 of \d+/);
    await expect(stepText).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/required|please fill/i);
    await expect(errorMessage).toBeVisible();
  });
});
